/**
 * One-time catalogue load for an empty database (the Romanian one).
 *
 * Runs before `next build`, and does nothing unless LOAD_CATALOGUE=1 is set on
 * the deployment. Even then it refuses to touch a database that already has
 * products, so a second deploy with the flag still on is harmless. Remove the
 * flag once the catalogue is in.
 *
 * Why this exists: the catalogue is generated by the seed routes, but the
 * longest of them (/api/seed/machines) outlasts a serverless function's time
 * limit, and the deployed app cannot be called from the build environment's
 * network. The same seeds were run once on a scratch database and exported to
 * data/ro-catalogue/*.json; this loads that export, ids and links intact, in
 * one transaction — all of it or none of it.
 *
 * Catalogue tables only. No orders, customers or users.
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import pg from 'pg'

if (process.env.LOAD_CATALOGUE !== '1') process.exit(0)

const url = process.env.DATABASE_URL
if (!url) {
  console.error('[catalogue] LOAD_CATALOGUE=1 but DATABASE_URL is not set.')
  process.exit(1)
}

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'data', 'ro-catalogue')
// Parents before children: products point at brands, rows of the others at products.
const TABLES = ['brands', 'categories', 'products', 'products_machines', 'products_rels', 'products_set_contents']

const client = new pg.Client({ connectionString: url })
await client.connect()
try {
  await client.query('BEGIN')
  // Two builds at once must not both load.
  await client.query('SELECT pg_advisory_xact_lock(8441001)')

  const { rows } = await client.query('SELECT count(*)::int AS n FROM products')
  if (rows[0].n > 0) {
    console.log(`[catalogue] products already has ${rows[0].n} rows — nothing loaded.`)
    await client.query('ROLLBACK')
    process.exit(0)
  }

  for (const table of TABLES) {
    const json = readFileSync(path.join(dir, `${table}.json`), 'utf8')
    const res = await client.query(
      `INSERT INTO public.${table} SELECT * FROM json_populate_recordset(null::public.${table}, $1::json)`,
      [json],
    )
    // Rows keep their ids, so a serial id has to move past them. The array
    // sub-tables (machines, set contents) use text ids and have no sequence.
    const seq = await client.query(`SELECT pg_get_serial_sequence('public.${table}', 'id') AS name`)
    if (seq.rows[0].name) {
      await client.query('SELECT setval($1::regclass, (SELECT max(id) FROM public.' + table + '))', [seq.rows[0].name])
    }
    console.log(`[catalogue] ${table}: ${res.rowCount} rows`)
  }
  await client.query('COMMIT')
  console.log('[catalogue] done.')
} catch (error) {
  await client.query('ROLLBACK').catch(() => {})
  console.error('[catalogue] failed, nothing was loaded:', error)
  process.exit(1)
} finally {
  await client.end()
}
